INSERT INTO yor_vpl VALUES ("ER2_6","016_2_6","EZR","2","6","6","Pahati-Moabu (láti ipasẹ̀ àwọn ọmọ Jeṣua àti Joabu) jẹ́ ẹgbẹ̀rún méjì àti ẹgbẹ̀rin lé méjìlá (2,812) ");
